alter table kaika_workshop.portfolios enable row level security; revoke all on kaika_workshop.portfolios from public,anon,authenticated;
alter table kaika_workshop.portfolio_goals enable row level security; revoke all on kaika_workshop.portfolio_goals from public,anon,authenticated;
